import{z as l,x as A,o as r,c as d,q as s,j as o,D as i,d as e,s as p,S as n,b as a}from"./chunks/framework.C8m1ZpeB.js";const I=JSON.parse('{"title":"posted interrupt","description":"","frontmatter":{"title":"posted interrupt","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/interrupt-virtualization.md","filePath":"cs/interrupt-virtualization.md","lastUpdated":1791413859000}'),B={name:"cs/interrupt-virtualization.md"};function u(P,t,C,D,c,m){const E=A("Mermaid");return r(),d("div",null,[t[2]||(t[2]=s('<h1 id="posted-interrupt" tabindex="-1">posted interrupt <a class="header-anchor" href="#posted-interrupt" aria-label="Permalink to &quot;posted interrupt&quot;">​</a></h1><div class="epigraph"><p>Posted interrupt 让宿主把客户中断描述直接写进内存描述符，CPU 在客户模式接受中断而不必每次 VM-exit 到 VMM 注入。</p><footer>—— 据 Intel 对 APICv/Posted Interrupt 的说明；KVM 中断虚拟化文档；[VM-exit](/cs/vmx-vmexit) 为代价先修</footer></div><p><a href="/cs/vfio">VFIO</a> 直通后 IRQ 仍可能打宿主。<a href="/cs/napi">NAPI</a> 在客户里。缺口是 <strong>中断虚拟化</strong>：APIC 虚拟化与 posted。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>传统：物理 IRQ → 宿主 → exit 注入客户。posted：硬件把中断记到 PID 描述符，客户 <code>sti</code> 时递送。缺口：vhost 与 irqfd 已减用户退出；posted 再减内核退出。本课不把 APIC 寄存器图抄完。</p><p><span class="marginnote">ARM GICv4 有类似 LPI 直投。对象是少 exit，不是实时保证。</span></p><p><span class="marginnote">「posted」可以翻译成「投递到信箱」：传统注入像快递员每次都把你从房间里叫出来（VM-exit）当面签收，posted 则是快递直接放进你门口的信箱（内存里的 PID 描述符），等你回到房间（客户开中断）时自己取，宿主全程不用出场。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>启用 APICv → 设备 MSI 指向 posted → 客户在非根模式收中断。对照 <a href="/cs/paravirtualization">半虚拟</a> virtio 中断：仍可走 eventfd。对照 <a href="/cs/preempt-rt">PREEMPT_RT</a>：宿主 RT 与客户中断是两层。</p>',9)),(r(),o(n,null,{default:i(()=>[p(E,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20DEV%5B%22%E8%AE%BE%E5%A4%87%20MSI%22%5D%20--%3E%20POST%5B%22Posted%20%E6%8F%8F%E8%BF%B0%E7%AC%A6%22%5D%0A%20%20POST%20--%3E%20G%5B%22%E5%AE%A2%E6%88%B7%E9%9D%9E%E6%A0%B9%E6%94%B6%E4%B8%AD%E6%96%AD%22%5D%0A%20%20OLD%5B%22%E6%97%A0%E8%99%9A%E6%8B%9F%E5%8C%96%22%5D%20--%3E%20EX%5B%22VM-exit%20%E6%B3%A8%E5%85%A5%22%5D%0A"})]),fallback:i(()=>[...t[0]||(t[0]=[e(" Loading... ",-1)])]),_:1})),t[3]||(t[3]=a("h2",{id:"机制",tabindex:"-1"},[e("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),t[4]||(t[4]=a("p",null,[e("中断虚拟化把「设备吵」从 VMM 热路径拿掉，使直通和 virtio 都能接近裸机 IRQ。不要写成 PIC 历史课。与 "),a("a",{href:"/cs/rss-multiqueue"},"RSS"),e("：客户内多队列仍要自己绑。")],-1)),t[5]||(t[5]=a("p",null,"无硬件支持则退回 exit 注入。",-1)),(r(),o(n,null,{default:i(()=>[p(E,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20IRQ%5B%22%E7%89%A9%E7%90%86%E4%B8%AD%E6%96%AD%E5%88%B0%E8%BE%BE%22%5D%20--%3E%20P%5B%22%E7%A1%AC%E4%BB%B6%E6%9F%A5%20PID%20%E6%8F%8F%E8%BF%B0%E7%AC%A6%22%5D%0A%20%20P%20--%3E%20NV%7B%22NV%20%E6%8C%87%E5%90%91%E7%9A%84%E5%AE%BF%E4%B8%BB%E5%90%91%E9%87%8F%3F%22%7D%0A%20%20NV%20--%3E%7C%22%E6%9C%89%E6%95%88%22%7C%20WFS%5B%22%E6%A3%80%E6%9F%A5%E5%AE%A2%E6%88%B7%20vCPU%20%E7%9A%84%20ON%20%E4%BD%8D%22%5D%0A%20%20WFS%20--%3E%20WAK%5B%22%E5%94%A4%E9%86%92%2F%E9%80%9A%E7%9F%A5%E7%9B%AE%E6%A0%87%20pCPU%22%5D%0A%20%20WAK%20--%3E%20G%5B%22%E5%AE%A2%E6%88%B7%E5%9C%A8%E9%9D%9E%E6%A0%B9%E6%A8%A1%E5%BC%8F%E5%8F%96%E4%B8%AD%E6%96%AD%EF%BC%8C%E7%A1%AC%E4%BB%B6%E6%90%AC%20PIR%20%E5%B9%B6%E6%B8%85%20ON%22%5D%0A%20%20NV%20--%3E%7C%22%E6%97%A0%E6%95%88%22%7C%20EXIT%5B%22%E9%80%80%E5%9B%9E%20VM-exit%20%E6%B3%A8%E5%85%A5%22%5D%0A%20%20G%20--%3E%20EOI%5B%22%E8%99%9A%E6%8B%9F%20EOI%20%E5%90%8E%E7%BB%AD%E6%8A%95%20PIR%20%E4%B8%AD%E4%B8%8B%E4%B8%80%E6%9D%A1%22%5D%0A"})]),fallback:i(()=>[...t[1]||(t[1]=[e(" Loading... ",-1)])]),_:1})),t[6]||(t[6]=s('<p><span class="marginnote">数字实例：一次 VM-exit 加上重新进入大约花 1–2 微秒。一张每秒打 10 万个中断的网卡，若每个中断都走退出注入，仅上下文进出就要吃掉约 0.1–0.2 秒的 CPU 时间（10 万 × 1.5 微秒 ≈ 15%），posted 把这笔开销几乎清零。</span></p><p><span class="marginnote">常见误区：初学者容易以为 posted interrupt 让中断「更快送达」。它的收益主要不是降低中断延迟，而是省掉 VMM 介入的 CPU 开销；极端情况下信箱转投（NV 重定向）甚至可能比直接注入多一跳。</span></p><p>实现上：irqfd 把事件 fd 接到注入路径，已比 ioctl 注入快。posted 再进一步让客户在非根模式收。无 APICv 时每个虚拟中断都可能 exit。 读法上只引用<a href="/cs/vfio">上一课</a>的结论，不把对象换成训练推理或限价簿。</p><p>本课在操作系统进阶的「虚拟化与隔离进阶 / Hypervisor」课序里，对象是 <strong>posted interrupt</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入所有 EOI 虚拟化细节。不保证旧 CPU。下一课时钟：客户看见的计时器。</p><p>版本字段会变，课序钉的是机制对象「posted interrupt」，不是某一主线内核的结构体名。 后课默认：客户中断可被 posted 减少 exit。时钟与 TSC 虚拟化，下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>posted/APICv 让客户在非根模式收中断。</li><li>目标是砍掉中断引起的 VM-exit。</li><li>时钟虚拟化是下一课。</li><li>出处：Intel SDM APIC virtualization；KVM。</li></ul>',10))])}const h=l(B,[["render",u]]);export{I as __pageData,h as default};
